    excerpt: 'Op maandag 26 oktober 2026 heeft het NCSC-NL een beveiligingsadvies met classificatie "Hoge kans / Hoge schade" gepubliceerd voor CVE-2026-111497 (in de sector aangeduid als "Node2Shell" of "HTTP2Shell", CVSS 8.8). Het betreft een kritieke out-of-bounds write / integer overflow in de Google Brotli-decompressiebibliotheek (versies 1.0.3 t/m 1.2.0). Wanneer een webserver, API-gateway, reverse proxy of applicatie in Node.js, Python, .NET of Windows PHP cURL automatisch een kwaadaardig gecomprimeerd HTTP-request of response met header "Content-Encoding: br" decomprimeert, kan een aanvaller zonder authenticatie een crash (DoS) of Remote Code Execution (RCE) veroorzaken. Google heeft het lek verholpen in Brotli 1.2.1 (en backports 1.1.1 en 1.0.10).',
