    excerpt: 'De Electronic Frontier Foundation (EFF) en Security.NL melden op 26 oktober 2026 een ongekende explosie in het aantal ontdekte softwarekwetsbaarheden: alleen al in de maand oktober 2026 zijn circa 13.000 nieuwe CVE\'s geregistreerd — ongeveer 3% van alle CVE\'s die ooit sinds de start van het systeem in 1999 zijn uitgegeven. Onderzoekers wijzen het grootschalige gebruik van geavanceerde AI-modellen en geautomatiseerde AI-fuzzers aan als hoofdoorzaak. Dit bevestigt de eerdere waarschuwing van de AIVD en MIVD (24 okt 2026) dat statelijke actoren (waaronder China) en cybercriminelen AI inzetten om in recordtempo zero-days te vinden in netwerkapparatuur en open-source bibliotheken voordat beheerders kunnen patchen.',
