    excerpt: 'Inlichtingendossier van de Algemene Inlichtingen- en Veiligheidsdienst (AIVD, onder leiding van directeur-generaal Simone Smit, die in maart 2026 Erik Akerboom opvolgde): (1) EXPLOSIEVE STIJGING CHINESE CYBERAANVALLEN MET AI OP EDGE DEVICES: In een gezamenlijk cyberadvies waarschuwen AIVD en MIVD dat Chinese staatshackers op grote schaal "edge devices" (firewalls, VPN-gateways, loadbalancers en routers aan de netwerkrand) aanvallen met behulp van AI en buitgemaakte broncode van westerse leveranciers. (2) CHINA GROOTSTE BEDREIGING ECONOMISCHE VEILIGHEID: De AIVD bestempelt China als het grootste gevaar voor de Nederlandse "kroonjuwelen" (ASML/NXP halfgeleiders, kwantumtechnologie, AI, ruimtevaart en maritieme sector) via hacks en wetenschapsspionage (TU Delft, Eindhoven, TNO). (3) KWANTUMCOMPUTER DREIGING ("HARVEST NOW, DECRYPT LATER"): Het Nationaal Bureau voor Verbindingsbeveiliging (NBV) van de AIVD roept op om direct over te stappen op Post-Quantum Cryptografie (PQC).',
