    mitreTechniques: ['T1190', 'T1078', 'T1059', 'T1505.003'],
    description: 'Drie urgente server- en infrastructuurwaarschuwingen van 5 en 6 november 2026 (gescrapet uit Security.NL posting/960618, 960523, 960654 en 960588 en de primaire bronnen NCSC-NL, OpenSSH, Alpine Linux, WatchTowr, Previdian Cyber, QNAP en Wordfence): (1) ACTIEF MISBRUIK VAN OPENSSH "*SSHOLE" AUTHENTICATIE-BYPASS (5 & 6 nov, posting/960618 & 960523, NCSC-2026-0469): Aanvallers maken actief misbruik van de kritieke "*SSHole"-kwetsbaarheid (ontdekt door Özgün Kültekin) op Linux-systemen die de musl C-library gebruiken (Alpine Linux, OpenWRT, Buildroot en Yocto). Wanneer een aanvaller een wachtwoord van meer dan 256 karakters meestuurt, geeft de crypt()-functie NULL terug, waardoor accounts zonder ingesteld wachtwoord of vergrendelde accounts ("!" / "*") direct te benaderen zijn. Onderzoekers van WatchTowr en Previdian Cyber zien dat aanvallers hiermee botnets en cryptominers installeren. OpenSSH heeft versie 10.6p2 met een mitigatie uitgebracht en het NCSC waarschuwt in advies NCSC-2026-0469. (2) QNAP WAARSCHUWT VOOR ACTIEF MISBRUIKTE "PLEX2SHELL" OP NAS (6 nov 15:15, posting/960654): QNAP roept alle NAS-gebruikers die Plex Media Server draaien op om direct te updaten naar versie 1.43.3.10861 of nieuwer. Een keten van vier kwetsbaarheden ("Plex2Shell") wordt op grote schaal misbruikt om mediaservers ongeauthenticeerd op afstand over te nemen. (3) 240.000+ AANVALLEN OP WORDPRESS CORE UPDATE-LEK CVE-2026-119977 (6 nov 10:38, posting/960588 & NCSC Alert): Zowel het NCSC als Wordfence waarschuwen dat aanvallers massaal WordPress-sites aanvallen via CVE-2026-119977 (meer dan 240.000 aanvallen in enkele dagen), waarmee een aanvaller tijdens het uitvoeren van een full-package update zichzelf administrator kan maken.',
