    description: 'Urgent Nederlands en Europees voedselketen-dossier van maandag 2 november 2026 (gescrapet uit Security.NL posting/960053, 959992 en 959936 en de primaire bronnen NCSC-NL, NOS, Danfoss, Previdian Cyber, Kevin Beaumont, Belga en HLN): (1) 17 NEDERLANDSE BEDRIJVEN EN TIENTALLEN BELGISCHE SUPERMARKTEN GETROFFEN: Aanvallers hebben in de nacht van zondag op maandag 2 november de koel- en vriesinstallaties gehackt van 17 bedrijven in Nederland (waaronder slagerijen en buurtwinkels) en tientallen supermarkten in België (waaronder filialen van Delhaize, Carrefour, Spar en slagerij De Laet & Van Haver), evenals winkels in Zweden (ICA), Luxemburg, Estland en Ierland. De aanvallers pasten de parameters aan en zetten de verdampers op "ontdooien", waardoor verwarmingselementen in de koelingen aansloegen (volgens bronnen tot wel 70 graden). Meerdere supermarkten moesten vandaag de deuren sluiten en al hun gekoelde voedselvoorraden vernietigen. (2) OORZAAK: DANFOSS STANDAARDWACHTWOORD "12345" EN 4G-INTERNETKOPPELING: Een woordvoerder van fabrikant Danfoss bevestigde tegenover de NOS dat de gehackte systemen gebruikmaakten van een standaardwachtwoord en niet op een beveiligd netwerk stonden. Cybersecuritybedrijf Previdian nam vanaf 27 oktober aanvallen waar waarbij met het standaard supervisor-wachtwoord "12345" werd ingelogd, en onderzoeker Kevin Beaumont toonde aan dat talloze Danfoss-managementinterfaces via een 4G-modem rechtstreeks voor heel het internet openstaan en patches missen. (3) SPOEDADVIES NCSC-NL (2 NOV 17:23): Het Nationaal Cyber Security Centrum (NCSC) waarschuwt dat de aanvallen de voedselveiligheid en bedrijfscontinuïteit direct bedreigen en roept alle supermarkten, slagerijen, koelhuizen en installateurs op om koelsystemen nooit rechtstreeks aan het internet te hangen, toegang te beperken tot vertrouwde IP-adressen/VPN, het standaardwachtwoord direct te vervangen en beveiligingsupdates te installeren.',
