    description: 'Actueel inlichtingendossier van de Algemene Inlichtingen- en Veiligheidsdienst (AIVD, vallend onder het Ministerie van Binnenlandse Zaken en Koninkrijksrelaties — BZK), onder leiding van directeur-generaal Simone Smit (die op 1 maart 2026 Erik Akerboom opvolgde na zijn zesjarige termijn): (1) EXPLOSIEVE STIJGING CHINESE CYBERAANVALLEN OP "EDGE DEVICES" MET BEHULP VAN AI (Oktober 2026): In een gezamenlijk cyberadvies waarschuwen de AIVD en MIVD voor een sterke toename van Chinese staatshacks op Nederlandse doelen. Chinese cyber-eenheden richten hun pijlen massaal op zogenaamde "edge devices" (apparaten aan de rand van het netwerk zoals firewalls, VPN-gateways, loadbalancers en mailgateways). Uit inlichtingen blijkt dat Chinese actoren westerse hard- en software tot in detail bestuderen (en soms zelfs over geheime broncode beschikken) en kunstmatige intelligentie (AI) inzetten om kwetsbaarheden nog sneller te vinden en direct uit te buiten. De Chinese ambassade in Nederland verwierp de beschuldigingen als ongegrond. (2) CHINA DE GROOTSTE BEDREIGING VOOR DE ECONOMISCHE VEILIGHEID ("KROONJUWELEN"): Zowel voormalig AIVD-baas Erik Akerboom als huidig DG Simone Smit benadrukken dat China de grootste bedreiging vormt voor de Nederlandse economische veiligheid. Chinese staatshackers én heimelijke kenniswervers richten zich structureel op de Nederlandse kroonjuwelen: de halfgeleider- en chipindustrie (ASML, NXP, ASM International), kwantumtechnologie, fotonica, AI, lucht- en ruimtevaart en de maritieme maakindustrie, evenals kennisinstellingen zoals TU Delft, TU Eindhoven en TNO. Bovendien nestelen Chinese groepen zich heimelijk in westerse vitale infrastructuur om bij een geopolitiek conflict (bijv. rond Taiwan) sabotage te kunnen plegen. (3) DREIGING VAN DE KWANTUMCOMPUTER ("HARVEST NOW, DECRYPT LATER" — Maart 2026): De AIVD (via het Nationaal Bureau voor Verbindingsbeveiliging, NBV) publiceerde in 2026 het dringende advies "Bescherm je nu tegen de dreiging van quantumcomputers". Vijandige staten slaan nú al op grote schaal onderschept, versleuteld Nederlands dataverkeer op ("harvest now, decrypt later"). Zodra krachtige kwantumcomputers beschikbaar komen, kunnen huidige RSA/ECC-versleutelingen met terugwerkende kracht worden gekraakt, waardoor staatsgeheimen en R&D-patenten die nog tientallen jaren geheim moeten blijven op straat komen te liggen. De AIVD roept de Rijksoverheid en vitale bedrijven op om nu direct de transitie naar Post-Quantum Cryptografie (PQC) te starten.',
